INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine APT immer auf staatliche Akteure beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kriminelle Gruppen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur staatlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt eine APT?', 3, '[{"text": "Langfristiger Datenraub", "correct": true, "because": "Fokus auf Persistenz"}, {"text": "Schnelle Zerstörung", "correct": false, "because": "Eher kurzfristig"}, {"text": "Öffentliche Aufmerksamkeit", "correct": false, "because": "Verdeckt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine APT?', 5, '[{"text": "Langfristigkeit", "correct": true, "because": "Anhaltende Bedrohung"}, {"text": "Verdeckte Vorgehensweise", "correct": true, "because": "Unauffällig"}, {"text": "Einmaliger Angriff", "correct": false, "because": "Persistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) APTs nutzen oft Social Engineering. b) Sie sind leicht zu erkennen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schwer erkennbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abwehr einer APT?', 4, '[{"text": "Netzwerküberwachung", "correct": false, "because": "Entdeckt Anomalien"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Verhindert Social Engineering"}, {"text": "Serverfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob APTs gezielte Angriffe sind?', 2, '[{"text": "Ja", "correct": true, "because": "Spezifische Ziele"}, {"text": "Nein", "correct": false, "because": "Nicht allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutzen APTs häufig?', 3, '[{"text": "Phishing", "correct": true, "because": "Einstieg durch Social Engineering"}, {"text": "Brute Force", "correct": false, "because": "Weniger verdeckt"}, {"text": "SQL-Injection", "correct": false, "because": "Spezifischer Angriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Abwehr von APTs?', 5, '[{"text": "Intrusion Detection", "correct": true, "because": "Erkennt Eindringlinge"}, {"text": "Regelmäßige Updates", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) APTs sind langfristig aktiv. b) Sie zielen nur auf große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Ziele möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei APTs unwichtig?', 4, '[{"text": "Verdecktheit", "correct": false, "because": "Kernmerkmal"}, {"text": "Persistenz", "correct": false, "because": "Definiert APT"}, {"text": "Serverdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind APTs kurzfristige Bedrohungen?', 2, '[{"text": "Nein", "correct": true, "because": "Langfristig angelegt"}, {"text": "Ja", "correct": false, "because": "Persistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine APT für Unternehmen?', 4, '[{"text": "Datenverlust", "correct": true, "because": "Langfristiger Raub"}, {"text": "Reputationsschaden", "correct": true, "because": "Vertrauensverlust"}, {"text": "Schnelle Erkennung", "correct": false, "because": "Schwer erkennbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass APTs immer Malware nutzen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch ohne Malware möglich"}, {"text": "Ja", "correct": false, "because": "Vielfältige Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich gegen APTs?', 3, '[{"text": "Proaktive Überwachung", "correct": true, "because": "Früherkennung"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Hardware-Upgrade", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) APTs sind gezielt. b) Sie sind leicht abwehrbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schwer abwehrbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine APT für Angreifer?', 5, '[{"text": "Langfristiger Zugriff", "correct": true, "because": "Dauerhafte Kontrolle"}, {"text": "Unauffälligkeit", "correct": true, "because": "Schwer erkennbar"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Langfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abwehr von APTs unwichtig?', 3, '[{"text": "Netzwerksegmentierung", "correct": false, "because": "Begrenzt Schaden"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Verhindert Einstieg"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzen APTs Zero-Day-Exploits?', 3, '[{"text": "Ja", "correct": true, "because": "Häufige Methode"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob APTs oft finanziell motiviert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Oft strategisch"}, {"text": "Ja", "correct": false, "because": "Abhängig, aber nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme wähle ich gegen APTs?', 4, '[{"text": "Threat Intelligence", "correct": true, "because": "Erkennt Bedrohungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutz"}, {"text": "Manuelle Updates", "correct": false, "because": "Zu langsam"}]');
